'use strict';

// MODULES //

var isinfinite = require( '@stdlib/math/base/assert/is-infinite' );
var copysign = require( '@stdlib/math/base/special/copysign' );
var signbit = require( '@stdlib/number/float64/base/signbit' );
var float64ToFloat32 = require( '@stdlib/number/float64/base/to-float32' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var atan2 = require( '@stdlib/math/base/special/atan2' );
var PINF = require( '@stdlib/constants/float64/pinf' );
var PI = require( '@stdlib/constants/float64/pi' );
var PI02F = require( '@stdlib/constants/float32/half-pi' );
var PI04F = require( '@stdlib/constants/float32/fourth-pi' );


// MAIN //

/**
* Computes the angle in the plane (in radians) between the positive x-axis and the ray from `(0,0)` to the point `(x,y)`.
*
* @param {number} y - `y` coordinate
* @param {number} x - `x` coordinate
* @returns {number} angle (in radians)
*
* @example
* var v = atan2f( 2.0, 2.0 ); // => atanf(1.0)
* // returns ~0.785
*
* @example
* var v = atan2f( 6.0, 2.0 ); // => atanf(3.0)
* // returns ~1.249
*
* @example
* var v = atan2f( -1.0, -1.0 ); // => atanf(1.0) - π
* // returns ~-2.356
*
* @example
* var v = atan2f( 3.0, 0.0 ); // => π/2
* // returns ~1.571
*
* @example
* var v = atan2f( -2.0, 0.0 ); // => -π/2
* // returns ~-1.571
*
* @example
* var v = atan2f( 0.0, 0.0 );
* // returns 0.0
*
* @example
* var v = atan2f( 3.0, NaN );
* // returns NaN
*
* @example
* var v = atan2f( NaN, 2.0 );
* // returns NaN
*/
function atan2f( y, x ) {
	var q;
	if ( isnanf( x ) || isnanf( y ) ) {
		return NaN;
	}
	x = float64ToFloat32( x );
	if ( isinfinite( x ) ) {
		if ( x === PINF ) {
			y = float64ToFloat32( y );
			if ( isinfinite( y ) ) {
				return copysign( PI04F, y );
			}
			return copysign( 0.0, y );
		}
		// Case: x is -Infinity
		if ( isinfinite( y ) ) {
			return copysign( 3.0*PI04F, y );
		}
		return copysign( PI, y );
	}
	if ( isinfinite( y ) ) {
		return copysign( PI02F, y );
	}
	if ( y === 0.0 ) {
		if ( x >= 0.0 && !signbit( x ) ) {
			return copysign( 0.0, y );
		}
		return copysign( PI, y );
	}
	if ( x === 0.0 ) {
		return copysign( PI02F, y );
	}
	q = atan2( y / x );
	if ( x < 0.0 ) {
		if ( q <= 0.0 ) {
			return q + PI;
		}
		return q - PI;
	}
	return q;
}


// EXPORTS //

module.exports = atan2f;
